// Validate the signed, short-lived request before any lookup or R2 access.
// OPERATIONS_REPORT_PDF_RELAY_SECRET is a protected n8n environment value.
const crypto = require('crypto');
const body = $json.body ?? {};
const reportKey = String(body.reportKey ?? '');
const issuedAt = Number(body.issuedAt);
const expiresAt = Number(body.expiresAt);
const nonce = String(body.nonce ?? '');
const correlationId = String(body.correlationId ?? '');
const disposition = String(body.disposition ?? '');
const signature = String(body.signature ?? '');
const secret = String($env.OPERATIONS_REPORT_PDF_RELAY_SECRET ?? '');
const now = Math.floor(Date.now() / 1000);
if (secret.length < 32 || !/^[a-z0-9][a-z0-9_.-]{1,120}$/.test(reportKey) || !Number.isSafeInteger(issuedAt) || !Number.isSafeInteger(expiresAt) || issuedAt > now + 15 || issuedAt < now - 120 || expiresAt <= now || expiresAt > issuedAt + 120 || !/^[a-f0-9]{64}$/.test(nonce) || !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(correlationId) || !['inline', 'attachment'].includes(disposition) || !/^[a-f0-9]{64}$/.test(signature)) throw new Error('PDF retrieval denied');
const canonical = [reportKey, issuedAt, expiresAt, nonce, correlationId, disposition].join('\n');
const expected = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) throw new Error('PDF retrieval denied');
const match = reportKey.match(/^cavetta\.monthly_maintenance\.(\d{4}-\d{2})$/);
if (!match) throw new Error('PDF retrieval denied');
return [{ json: { reportKey, reportMonth: match[1], reportType: 'MONTHLY_MAINTENANCE', issuedAt, expiresAt, nonce, correlationId, disposition, signature } }];

// Reload and strictly validate the authoritative n8n report. No fields are changed.
const requested = $('Validate Signed Request').first().json;
const rows = $input.all().map((item) => item.json ?? {}).filter((row) => Object.keys(row).length > 0 && String(row.reportMonth ?? '').trim() === requested.reportMonth && String(row.reportType ?? '').trim().toUpperCase() === requested.reportType);
if (rows.length !== 1) throw new Error('PDF retrieval denied');
const row = rows[0];
const state = String(row.documentStatus ?? '').trim().toUpperCase();
const objectKey = String(row.pdfDriveFileId ?? '').trim();
const fileName = String(row.pdfFileName ?? '').trim();
const generatedAt = String(row.pdfGeneratedAt ?? '').trim();
if (!['DRAFT', 'APPROVED', 'SENDING', 'SENT', 'REJECTED', 'SEND_FAILED'].includes(state) || !/^Cavetta Maintenance Reports\/\d{4}\/[^/\\]{1,180}\.pdf$/i.test(objectKey) || !/^[^/\\]{1,180}\.pdf$/i.test(fileName) || objectKey.includes('..') || fileName.includes('..') || !Number.isFinite(Date.parse(generatedAt)) || !objectKey.endsWith('/' + fileName)) throw new Error('PDF retrieval denied');
return [{ json: { objectKey } }];

// Validate the binary before responding. Do not log or convert PDF bytes to JSON.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buffer.length < 5 || buffer.length > 25 * 1024 * 1024 || buffer.subarray(0, 5).toString('ascii') !== '%PDF-') throw new Error('PDF retrieval denied');
const item = $input.item;
if (!item.binary?.data) throw new Error('PDF retrieval denied');
item.binary.data.mimeType = 'application/pdf';
item.binary.data.fileExtension = 'pdf';
item.binary.data.fileName = 'report.pdf';
return item;
